-- ESB KAMONYI - ECOLE SAINTE BERNADETTE KAMONYI schema (MySQL 8)
CREATE DATABASE IF NOT EXISTS esb_kamonyi CHARACTER SET utf8mb4;
USE esb_kamonyi;
CREATE TABLE IF NOT EXISTS users (id VARCHAR(40) PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(150) NOT NULL UNIQUE, pass VARCHAR(255) NOT NULL, role ENUM('admin','teacher','student','parent') NOT NULL, active TINYINT DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS classes (id VARCHAR(40) PRIMARY KEY, name VARCHAR(50) NOT NULL, level VARCHAR(50), teacher_id VARCHAR(40), academic_year VARCHAR(20));
CREATE TABLE IF NOT EXISTS subjects (id VARCHAR(40) PRIMARY KEY, name VARCHAR(100) NOT NULL, code VARCHAR(20), max_marks INT DEFAULT 100);
CREATE TABLE IF NOT EXISTS students (id VARCHAR(40) PRIMARY KEY, student_id VARCHAR(40) UNIQUE, name VARCHAR(150) NOT NULL, gender ENUM('Male','Female'), dob DATE, class_id VARCHAR(40), parent VARCHAR(150), phone VARCHAR(30), email VARCHAR(150), address VARCHAR(255), admission_date DATE, academic_year VARCHAR(20), status VARCHAR(20) DEFAULT 'active', FOREIGN KEY (class_id) REFERENCES classes(id));
CREATE TABLE IF NOT EXISTS teachers (id VARCHAR(40) PRIMARY KEY, user_id VARCHAR(40), name VARCHAR(150) NOT NULL, gender VARCHAR(10), phone VARCHAR(30), email VARCHAR(150), subject VARCHAR(100), department VARCHAR(100), qualification VARCHAR(150), status VARCHAR(20) DEFAULT 'active');
CREATE TABLE IF NOT EXISTS parents (id VARCHAR(40) PRIMARY KEY, user_id VARCHAR(40), name VARCHAR(150), phone VARCHAR(30), email VARCHAR(150), status VARCHAR(20) DEFAULT 'active');
CREATE TABLE IF NOT EXISTS parent_children (parent_id VARCHAR(40), student_id VARCHAR(40), PRIMARY KEY(parent_id, student_id));
CREATE TABLE IF NOT EXISTS academic_years (id VARCHAR(40) PRIMARY KEY, name VARCHAR(20), is_current TINYINT DEFAULT 0);
CREATE TABLE IF NOT EXISTS terms (id VARCHAR(40) PRIMARY KEY, name VARCHAR(50), year_id VARCHAR(40));
CREATE TABLE IF NOT EXISTS attendance (id VARCHAR(40) PRIMARY KEY, class_id VARCHAR(40), date DATE NOT NULL, student_id VARCHAR(40), status ENUM('present','absent','late','excused') DEFAULT 'present');
CREATE TABLE IF NOT EXISTS examinations (id VARCHAR(40) PRIMARY KEY, name VARCHAR(120), type VARCHAR(50), term VARCHAR(50), academic_year VARCHAR(20), start_date DATE, end_date DATE, status VARCHAR(20));
CREATE TABLE IF NOT EXISTS marks (id VARCHAR(40) PRIMARY KEY, exam_id VARCHAR(40), student_id VARCHAR(40), subject VARCHAR(100), score DECIMAL(6,2), max_marks DECIMAL(6,2) DEFAULT 100);
CREATE TABLE IF NOT EXISTS assignments (id VARCHAR(40) PRIMARY KEY, title VARCHAR(200), subject VARCHAR(100), class_id VARCHAR(40), instructions TEXT, deadline DATE, created_by VARCHAR(150), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS submissions (id VARCHAR(40) PRIMARY KEY, assignment_id VARCHAR(40), student_id VARCHAR(40), content TEXT, file_url VARCHAR(255), score DECIMAL(6,2), feedback TEXT, submitted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS learning_materials (id VARCHAR(40) PRIMARY KEY, title VARCHAR(200), subject VARCHAR(100), class_id VARCHAR(40), type VARCHAR(20), url VARCHAR(255), uploaded_by VARCHAR(150));
CREATE TABLE IF NOT EXISTS quizzes (id VARCHAR(40) PRIMARY KEY, title VARCHAR(200), subject VARCHAR(100), class_id VARCHAR(40), duration_min INT DEFAULT 15, questions JSON);
CREATE TABLE IF NOT EXISTS quiz_attempts (id VARCHAR(40) PRIMARY KEY, quiz_id VARCHAR(40), student_id VARCHAR(40), answers JSON, score DECIMAL(6,2), attempted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS fees (id VARCHAR(40) PRIMARY KEY, class_id VARCHAR(40), term VARCHAR(50), amount DECIMAL(12,2), academic_year VARCHAR(20));
CREATE TABLE IF NOT EXISTS payments (id VARCHAR(40) PRIMARY KEY, student_id VARCHAR(40), amount DECIMAL(12,2), date DATE, method VARCHAR(30), receipt VARCHAR(50), received_by VARCHAR(150));
CREATE TABLE IF NOT EXISTS admissions (id VARCHAR(40) PRIMARY KEY, student_name VARCHAR(150), parent_name VARCHAR(150), phone VARCHAR(30), class_requested VARCHAR(50), status VARCHAR(20) DEFAULT 'pending', date TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS announcements (id VARCHAR(40) PRIMARY KEY, title VARCHAR(200), body TEXT, audience VARCHAR(20) DEFAULT 'all', date DATE, author VARCHAR(150));
CREATE TABLE IF NOT EXISTS news (id VARCHAR(40) PRIMARY KEY, title VARCHAR(200), body TEXT, date DATE, author VARCHAR(150), category VARCHAR(50));
CREATE TABLE IF NOT EXISTS events (id VARCHAR(40) PRIMARY KEY, title VARCHAR(200), description TEXT, date DATE, location VARCHAR(150), category VARCHAR(50));
CREATE TABLE IF NOT EXISTS gallery (id VARCHAR(40) PRIMARY KEY, title VARCHAR(200), category VARCHAR(50), url VARCHAR(255));
CREATE TABLE IF NOT EXISTS notifications (id VARCHAR(40) PRIMARY KEY, user_id VARCHAR(40), title VARCHAR(200), body TEXT, date TIMESTAMP DEFAULT CURRENT_TIMESTAMP, is_read TINYINT DEFAULT 0);
CREATE TABLE IF NOT EXISTS settings (k VARCHAR(100) PRIMARY KEY, v TEXT);
CREATE TABLE IF NOT EXISTS audit_logs (id INT AUTO_INCREMENT PRIMARY KEY, actor VARCHAR(150), action VARCHAR(255), at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
INSERT IGNORE INTO settings (k,v) VALUES ('schoolName','ESB KAMONYI'),('fullName','ECOLE SAINTE BERNADETTE KAMONYI'),('address','Kamonyi District, Southern Province, Rwanda'),('phone','+250 788 000 000'),('email','info@esbkamonyi.rw');
